package com.bank.spi.impl;

import com.bank.spi.FeeCalculator;
import java.math.BigDecimal;

// PROVIDER 1: must have a public no-arg constructor for ServiceLoader.
public class GstFeeCalculator implements FeeCalculator {
    public GstFeeCalculator() { }
    public String name() { return "GST-18%"; }
    public BigDecimal feeFor(String accountId, BigDecimal balance) {
        // 0.1% service fee plus 18% GST on that fee.
        BigDecimal base = balance.multiply(new BigDecimal("0.001"));
        return base.add(base.multiply(new BigDecimal("0.18"))).setScale(2, java.math.RoundingMode.HALF_UP);
    }
}
