package com.bank.billing;

import com.bank.spi.FeeCalculator;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class BillingEngine {
    private static final Logger log = Logger.getLogger(BillingEngine.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Load ALL FeeCalculator providers. Uses the thread context class loader.
        ServiceLoader<FeeCalculator> loader = ServiceLoader.load(FeeCalculator.class);

        BigDecimal rajeshTotal = BigDecimal.ZERO;
        BigDecimal priyaTotal  = BigDecimal.ZERO;

        // LAZY: each provider is instantiated only as we iterate. Defensive skip on error.
        var iterator = loader.iterator();
        while (iterator.hasNext()) {
            FeeCalculator calc;
            try {
                calc = iterator.next();   // provider loaded + instantiated HERE, lazily
            } catch (ServiceConfigurationError e) {
                log.severe(() -> "Skipping broken provider: " + e.getMessage());
                continue;
            }
            BigDecimal rFee = calc.feeFor("SAV2001", new BigDecimal("1000000.00"));  // Rajesh
            BigDecimal pFee = calc.feeFor("CUR3001", new BigDecimal("250000.00"));   // Priya
            rajeshTotal = rajeshTotal.add(rFee);
            priyaTotal  = priyaTotal.add(pFee);
            log.info(() -> "Provider " + calc.name() + " → Rajesh Rs." + rFee + ", Priya Rs." + pFee);
        }
        final BigDecimal rt = rajeshTotal, pt = priyaTotal;
        log.info(() -> "Total fees — Rajesh: Rs." + rt + ", Priya: Rs." + pt);
    }
}
